{"content":"package store

import (
	"bytes"
	"errors"
	"strings"
	"sync"
	"testing"
	"time"
)

// fakeClock is a manually advanced clock.
type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Add(d time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(d)
	c.mu.Unlock()
}

func newStore(clock Clock) *Store { return New(clock) }

func TestSetGet(t *testing.T) {
	s := newStore(newFakeClock())
	s.Set("a", "1", 0)
	v, ok := s.Get("a")
	if !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v", v, ok)
	}
	if _, ok := s.Get("missing"); ok {
		t.Fatal("missing key reported present")
	}
	// Set replaces both value and ttl.
	s.Set("a", "2", time.Minute)
	v, _ = s.Get("a")
	if v != "2" {
		t.Fatalf("Get(a) after re-Set = %q", v)
	}
	s.Set("a", "3", 0)
	if d := s.TTL("a"); d != -1*time.Second {
		t.Fatalf("TTL(a) = %v, want -1s", d)
	}
}

func TestExpiry(t *testing.T) {
	c := newFakeClock()
	s := newStore(c)
	s.Set("a", "1", time.Second)
	s.Set("b", "2", 0)
	if s.Len() != 2 {
		t.Fatalf("Len = %d, want 2", s.Len())
	}
	c.Add(time.Second) // now == deadline for a -> expired
	if s.Exists("a") {
		t.Fatal("a should be expired at deadline")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("a should be missing after expiry")
	}
	if got := s.Len(); got != 1 {
		t.Fatalf("Len after expiry = %d, want 1", got)
	}
	if got := s.Del("a"); got != 0 {
		t.Fatalf("Del expired = %d, want 0", got)
	}
	if got := s.Del("b"); got != 1 {
		t.Fatalf("Del b = %d, want 1", got)
	}
}

func TestExpirePersist(t *testing.T) {
	c := newFakeClock()
	s := newStore(c)
	if s.Expire("nope", time.Second) {
		t.Fatal("Expire on missing key = true")
	}
	s.Set("a", "1", 0)
	if !s.Expire("a", 5*time.Second) {
		t.Fatal("Expire on live key = false")
	}
	if d := s.TTL("a"); d != 5*time.Second {
		t.Fatalf("TTL = %v, want 5s", d)
	}
	if d := s.TTL("missing"); d != -2*time.Second {
		t.Fatalf("TTL(missing) = %v, want -2s", d)
	}
	if !s.Persist("a") {
		t.Fatal("Persist on key with expiry = false")
	}
	if d := s.TTL("a"); d != -1*time.Second {
		t.Fatalf("TTL after Persist = %v, want -1s", d)
	}
	if s.Persist("a") {
		t.Fatal("Persist on key without expiry = true")
	}
	if !s.Expire("a", 0) {
		t.Fatal("Expire ttl<=0 should delete key and return true")
	}
	if s.Exists("a") {
		t.Fatal("a should be deleted")
	}
}

func TestIncr(t *testing.T) {
	c := newFakeClock()
	s := newStore(c)
	if v, err := s.Incr("n", 1); err != nil || v != 1 {
		t.Fatalf("Incr missing = %d, %v", v, err)
	}
	if v, err := s.Incr("n", 10); err != nil || v != 11 {
		t.Fatalf("Incr existing = %d, %v", v, err)
	}
	s.Set("n", "5", 0)
	if v, err := s.Incr("n", -3); err != nil || v != 2 {
		t.Fatalf("Incr negative = %d, %v", v, err)
	}
	// keeps existing ttl
	s.Set("x", "1", 3*time.Second)
	s.Incr("x", 1)
	if d := s.TTL("x"); d != 3*time.Second {
		t.Fatalf("TTL after Incr = %v, want 3s", d)
	}
	// ttl <= 0 (no expiry) is also kept
	s.Set("x", "1", 0)
	s.Incr("x", 1)
	if d := s.TTL("x"); d != -1*time.Second {
		t.Fatalf("TTL after Incr no-expiry = %v, want -1s", d)
	}
	s.Set("s", "abc", 0)
	if _, err := s.Incr("s", 1); !errors.Is(err, ErrNotInteger) {
		t.Fatalf("Incr non-int err = %v, want ErrNotInteger", err)
	}
	s.Set("big", "9223372036854775807", 0)
	if _, err := s.Incr("big", 1); !errors.Is(err, ErrNotInteger) {
		t.Fatalf("Incr overflow err = %v, want ErrNotInteger", err)
	}
}

func TestKeysGlob(t *testing.T) {
	s := newStore(newFakeClock())
	s.Set("user:1", "a", 0)
	s.Set("user:2", "b", 0)
	s.Set("user:10", "c", 0)
	s.Set("item/1", "d", 0)
	s.Set("apple", "e", 0)

	if got := s.Keys("*"); len(got) != 5 {
		t.Fatalf("Keys(*) = %v", got)
	}
	if got := s.Keys("user:*"); len(got) != 3 || got[0] != "user:1" || got[1] != "user:10" || got[2] != "user:2" {
		t.Fatalf("Keys(user:*) = %v, want sorted [user:1 user:10 user:2]", got)
	}
	// * must match '/'
	if got := s.Keys("item/*"); len(got) != 1 || got[0] != "item/1" {
		t.Fatalf("Keys(item/*) = %v", got)
	}
	if got := s.Keys("user:?"); len(got) != 2 {
		t.Fatalf("Keys(user:?) = %v", got)
	}
	if got := s.Keys("user:1?"); len(got) != 1 || got[0] != "user:10" {
		t.Fatalf("Keys(user:1?) = %v", got)
	}
	if got := s.Keys("user:[12]"); len(got) != 2 {
		t.Fatalf("Keys(user:[12]) = %v", got)
	}
	if got := s.Keys("user:[0-2]"); len(got) != 3 {
		t.Fatalf("Keys(user:[0-2]) = %v", got)
	}
	if got := s.Keys("user:[!1]"); len(got) != 2 {
		t.Fatalf("Keys(user:[!1]) = %v", got)
	}
	if got := s.Keys("user:[^1]"); len(got) != 2 {
		t.Fatalf("Keys(user:[^1]) = %v", got)
	}
	if got := s.Keys(`user:\:1`); len(got) != 1 || got[0] != "user:1" {
		t.Fatalf(`Keys(user:\:1) = %v`, got)
	}
	if got := s.Keys("a?gle"); len(got) != 1 || got[0] != "apple" {
		t.Fatalf("Keys(a?gle) = %v", got)
	}
	if got := s.Keys("a[bc]le"); len(got) != 0 {
		t.Fatalf("Keys(a[bc]le) = %v, want empty", got)
	}
	if got := s.Keys(""); len(got) != 0 {
		t.Fatalf(`Keys("") = %v, want empty`, got)
	}
	// expired keys are excluded
	c := newFakeClock()
	s2 := newStore(c)
	s2.Set("k1", "v", time.Second)
	s2.Set("k2", "v", 0)
	c.Add(time.Minute)
	if got := s2.Keys("*"); len(got) != 1 || got[0] != "k2" {
		t.Fatalf("Keys after expiry = %v", got)
	}
}

func TestMatchUnit(t *testing.T) {
	cases := []struct{ pattern, key string; want bool }{
		{"*", "anything/here", true},
		{"*", "", true},
		{"a*b", "a", true},
		{"a*b", "aXb", true},
		{"a*b", "ab", true},
		{"a*b", "ba", false},
		{"**", "x", true},
		{"a*bc", "abc", true},
		{"a?c", "abc", true},
		{"a?c", "ac", false},
		{"[abc]x", "bx", true},
		{"[abc]x", "dx", false},
		{"[a-c]x", "bx", true},
		{"[a-c]x", "dx", false},
		{"[^a]x", "bx", true},
		{"[^a]x", "ax", false},
		{"[!a]x", "bx", true},
		{"[!a]x", "ax", false},
		{`a\b`, `a\b`, true},
		{`a\b`, `ab`, false},
		{"a", "a", true},
		{"a", "ab", false},
		{"a", "b", false},
		{"", "", true},
	}
