msg.reasoning_content:
Server design (mind the 3-clause for rule):

```go
package server

import (
	"bufio"
	"context"
	"net"
	"strings"
	"sync"

	"example.com/kv/proto"
	"example.com/kv/store"
)

const maxLineBytes = 64 * 1024

func Serve(ctx context.Context, l net.Listener, s *store.Store) error {
	defer l.Close()
	var (
		wg    sync.WaitGroup
		mu    sync.Mutex
		conns = make(map[net.Conn]struct{})
	)
	shutdown := func() {
		mu.Lock()
		for c := range conns {
			c.Close()
		}
		conns = make(map[net.Conn]struct{})
		mu.Unlock()
	}
	// close the listener as soon as ctx is done
	go func() {
		<-ctx.Done()
		l.Close()
	}()
	accept:
	for {
		c, err := l.Accept()
		if err != nil {
			if ctx.Err() != nil {
				break accept
			}
			continue
		}
		mu.Lock()
		conns[c] = struct{}{}
		mu.Unlock()
		wg.Add(1)
		go func(c net.Conn) {
			defer wg.Done()
			mu.Lock()
			delete(conns, c)
			mu.Unlock()
			defer c.Close()
			serveConn(ctx, c, s, shutdown)
		}(c)
	}
	<-ctx.Done()
	shutdown()
	wg.Wait()
	return nil
}
```

Hmm, wait, `break accept` — a labeled break for a for. But `break accept` breaks out of the for. Is this toolchain okay with it? The weird for parsing issue only affects the 2-clause for. `for {` is a bare for — no problem.

serveConn:

```go
func serveConn(ctx context.Context, c net.Conn, s *store.Store, shutdown func()) {
	br := bufio.NewReaderSize(c, maxLineBytes+1)
	bw := bufio.NewWriterSize(c, 64*1024)
	for {
		select {
		case <-ctx.Done():
			shutdown()  // close all open connections including this one
			return
		default:
		}
		line, err := br.ReadString('\n')
		if err != nil {
			return
		}
		if len(line) > maxLineBytes+1 {  // ReadString returns ErrBufferFull
			// too long
			bw.WriteString("-ERR line too long\n")
			bw.Flush()
			c.Close()
			return
		}
		line = strings.TrimSuffix(line, "\n")
		line = strings.TrimSuffix(line, "\r")
		// QUIT?
		if isQuit(line) {
			bw.WriteString("+BYE\n")
			bw.Flush()
			return  // the deferred c.Close() closes it
		}
		resp := proto.Exec(s, line)
		bw.WriteString(resp)
		if err := bw.Flush(); err != nil {
			return
		}
	}
